//###########################################################
extractRelevantDates = function(num, dateTo, dates, isWeekly = false) {
  var d, datesToScreen, halfTimeFrameD, i, j, lastPossibleDate, lastRelevantDate, nextDates, today;
  if (dates.length === 0) {
    return {};
  }
  if (isWeekly) {
    halfTimeFrameD = 4;
  } else {
    halfTimeFrameD = 14;
  }
  today = (new Date()).toISOString().slice(0, 10);
  if (dateTo == null) {
    dateTo = today;
  }
  //# We cannot backtest event which has not completed the TimeFrame for backtesting
  d = new Date();
  d.setDate(d.getDate() - halfTimeFrameD);
  lastPossibleDate = d.toISOString().slice(0, 10);
  
  //# If our chosen dateTo is later then the last Possible date then take last possible date
  if (lastPossibleDate < dateTo) {
    lastRelevantDate = lastPossibleDate;
  } else {
    lastRelevantDate = dateTo;
  }
  i = 0;
  d = dates[i];
  while (d < lastRelevantDate) {
    d = dates[++i];
    if (i === dates.length - 1) {
      console.error("We donot have newer dates 0!");
      return {};
    }
  }
  
  //# last num relevant dates are screened for
  //# Aha! So this is why many times num is off...
  j = i - num;
  if (j < 0) {
    j = 0;
  }
  datesToScreen = dates.slice(j, i);
  olog({dates, datesToScreen, num, i, j});
  while (d < today) {
    d = dates[++i];
    if (i === dates.length - 1) {
      console.error("We donot have newer dates 1!");
      return {};
    }
  }
  nextDates = dates.slice(i);
  log(nextDates);
  return {datesToScreen, nextDates};
};

//###########################################################
dateFromNumEvents = function(num, toDate, evnt) {
  var i, targetIdx;
  if (toDate == null) {
    toDate = (new Date()).toISOString().slice(0, 10);
  }
  if ((num == null) || num <= 0) {
    return toDate;
  }
  if ((evnt.dates == null) || evnt.dates.length === 0) {
    return toDate;
  }
  i = 0;
  while (i < evnt.dates.length && evnt.dates[i] < toDate) {
    i++;
  }
  if (i === 0) {
    return toDate; // all events are in the future
  }
  targetIdx = i - num;
  if (targetIdx < 0) {
    targetIdx = 0;
  }
  return evnt.dates[targetIdx];
};

numEventsForDateRange = function(fromDate, toDate, evnt) {
  var endIdx, num, startIdx;
  if (fromDate == null) {
    return 0; // no default fromDate
  }
  if (toDate == null) {
    toDate = (new Date()).toISOString().slice(0, 10); // default toDate is today
  }
  if (fromDate >= toDate) {
    return 0;
  }
  if ((evnt.dates == null) || evnt.dates.length === 0) {
    return 0;
  }
  // Find start index - also counts date == fromDate!
  startIdx = 0;
  while (startIdx < evnt.dates.length && evnt.dates[startIdx] < fromDate) {
    startIdx++;
  }
  // Find end index - doesn't use date == toDate
  endIdx = 0;
  while (endIdx < evnt.dates.length && evnt.dates[endIdx] < toDate) {
    endIdx++;
  }
  num = endIdx - startIdx;
  if (num < 0) {
    return 0;
  }
  return num;
};

