numRangeKeyDowned = function(evnt) {
  var ctrlKey, input, key, metaKey;
  // log "inputKeyDowned"
  ({key, ctrlKey, metaKey} = evnt);
  // value = evnt.target.value
  input = evnt.target;
  //# allow numbers, nav and editing
  if (ctrlKey || metaKey || navKeys.has(key) || numKeys.has(key)) {
    return;
  }
  if (key === 'Enter') {
    evnt.preventDefault();
    input.blur();
    return;
  }
  // next = getNextFocusableValueInput(input)
  // if next? then next.focus()
  // else input.blur()
  if (key === 'Escape') {
    evnt.preventDefault();
    input.value = ""; // this will take latest known value
    input.blur();
    return;
  }
  evnt.preventDefault();
};

